def find_vote_inits(provider: Provider, deck: Deck) -> Iterable[Vote]:
    """find vote_inits on this deck"""
    return Vote.objects.filter(
        provider=provider,
        deck=deck,
        vote_init__isnull=False,
        vote_init__is_active=True
    )

